import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import type { AuthEventType } from "../../shared/auth-events";
import { user } from "./auth-schema";

// Our own table, not generated by the Better-Auth CLI: a per-user security log.
// No IP address: city, country and network say more to a person, and with a
// VPN the IP is no more accurate than they are.
export const authEvent = sqliteTable(
  "auth_event",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    type: text("type").$type<AuthEventType>().notNull(),
    method: text("method"),
    device: text("device"),
    city: text("city"),
    country: text("country"),
    network: text("network"),
    createdAt: integer("created_at", { mode: "timestamp_ms" })
      .notNull()
      .$defaultFn(() => new Date()),
  },
  (table) => [index("auth_event_userId_createdAt_idx").on(table.userId, table.createdAt)],
);
